document.addEventListener("DOMContentLoaded",init);function init(){renderCategoryStrip("category-strip");document.getElementById("search-form").addEventListener("submit",onSearchSubmit);startSearchPrompts();loadHomePageData()}const SEARCH_PROMPTS=["What is on your mind?","Ask Mwakete…","Try using Kiribati language."];const SEARCH_PROMPT_MS=3500;function startSearchPrompts(){const input=document.getElementById("search-input");if(!input)return;input.setAttribute("aria-label","Search products, services and rentals");input.placeholder=SEARCH_PROMPTS[0];const reduced=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;if(reduced)return;let i=0;const timer=setInterval(()=>{i=(i+1)%SEARCH_PROMPTS.length;input.placeholder=SEARCH_PROMPTS[i]},SEARCH_PROMPT_MS);const stop=()=>clearInterval(timer);input.addEventListener("focus",stop,{once:true});input.addEventListener("input",stop,{once:true})}function onSearchSubmit(e){e.preventDefault();const q=document.getElementById("search-input").value.trim();window.location.href=`categories.html?q=${encodeURIComponent(q)}`}async function loadHomePageData(){const productsStatusEl=document.getElementById("trending-products-status");const storesStatusEl=document.getElementById("trending-stores-status");const stopProductsLoading=startLoadingMessage(productsStatusEl);const stopStoresLoading=startLoadingMessage(storesStatusEl);const request=Api.get("getHomePageData",{});window.__criticalReady=request;const res=await request;stopProductsLoading();stopStoresLoading();if(!res.ok){showLoadFailedMessage(productsStatusEl);showLoadFailedMessage(storesStatusEl);return}renderTrendingProducts(res.products);renderTrendingStores(res.stores)}function renderTrendingProducts(products){const statusEl=document.getElementById("trending-products-status");const listEl=document.getElementById("trending-products-list");if(products.length===0){statusEl.textContent="No products yet.";return}statusEl.textContent="";listEl.innerHTML=products.map(p=>renderBrowseProductCard(p,{showLocation:true})).join("");mountBadgeLegend("home-badge-legend",products);recordProductViewsOnce(products.map(p=>p.productId))}function renderTrendingStores(stores){const statusEl=document.getElementById("trending-stores-status");const listEl=document.getElementById("trending-stores-list");if(stores.length===0){statusEl.textContent="No stores yet.";return}statusEl.textContent="";listEl.innerHTML=stores.map(renderLogoCarouselItem).join("")}